mapper.select:
SELECT ea.id, ea.drug_id, ea.hospital_id, ea.inventory_id, ea.batch_no, ea.expire_date, ea.days_until_expiry, ea.status, ea.created_at, ea.updated_at, d.name AS drug_name, d.code AS drug_code, d.spec, d.unit, h.name AS hospital_name FROM drug_expiry_alert ea LEFT JOIN drug_info d ON ea.drug_id = d.id LEFT JOIN hospital h ON ea.hospital_id = h.id
AND ea.status = #{status}
ORDER BY ea.days_until_expiry ASC, ea.created_at DESC
